(()=>{const key='goride-trip-selection',fields=['location','car','mode','startDate','endDate'];function clean(v){const out={};for(const field of fields){const value=v?.[field];if(typeof value!=='string'||value.length>100)continue;if(field==='mode'&&!['self','driver'].includes(value))continue;if(field.endsWith('Date')&&(!/^\d{4}-\d{2}-\d{2}$/.test(value)||Number.isNaN(Date.parse(value+'T00:00:00Z'))))continue;out[field]=value;}return out;}window.GoRideTrip={save(value){const trip=clean(value);try{sessionStorage.setItem(key,JSON.stringify({trip,saved:Date.now()}));}catch{}return trip;},read(search=''){let trip={};try{const saved=JSON.parse(sessionStorage.getItem(key)||'null');if(saved&&Date.now()-saved.saved<1800000)trip=clean(saved.trip);}catch{}const explicit=clean(Object.fromEntries(new URLSearchParams(search)));return {...trip,...explicit};},url(value){return '/account?'+new URLSearchParams(clean(value)).toString()+'#new-request';}};})();
